class EventTicket3{protected double balanceDue;private double[] fees=new double[10];private int feeCount;EventTicket3(double p){if(p<=0)throw new IllegalArgumentException();balanceDue=p;}void pay(double a){if(a>0)balanceDue=Math.max(0,balanceDue-a);}protected void applyLateFee(double amount){if(amount>0){balanceDue+=amount;if(feeCount<fees.length)fees[feeCount++]=amount;}}double[] getPenaltyHistory(){double[] r=new double[feeCount];System.arraycopy(fees,0,r,0,feeCount);return r;}}
class WorkshopTicket3 extends EventTicket3{WorkshopTicket3(double p){super(p);}@Override protected void applyLateFee(double amount){super.applyLateFee(amount*2);}}
public class Problem3{public static void main(String[]x){WorkshopTicket3 w=new WorkshopTicket3(200);w.pay(200);w.applyLateFee(100);System.out.println(w.getBalanceDue());System.out.println(w.getPenaltyHistory()[0]);}}
